import unittest
from datetime import datetime, timedelta, timezone

from coupon import Coupon, redeem

SH = timezone(timedelta(hours=8))


class TestCouponExpiryContract(unittest.TestCase):
    def test_morning_of_last_day_not_expired(self):
        c = Coupon("A")
        self.assertFalse(c.is_expired(datetime(2026, 11, 10, 9, 0, tzinfo=SH)))

    def test_evening_of_last_day_not_expired(self):
        c = Coupon("A")
        self.assertFalse(c.is_expired(datetime(2026, 11, 10, 18, 0, tzinfo=SH)))

    def test_last_second_of_last_day_not_expired(self):
        c = Coupon("A")
        self.assertFalse(c.is_expired(datetime(2026, 11, 10, 23, 59, 59, tzinfo=SH)))

    def test_next_day_expired(self):
        c = Coupon("A")
        self.assertTrue(c.is_expired(datetime(2026, 11, 11, 0, 0, tzinfo=SH)))

    def test_redeem_ok_within_validity(self):
        r = redeem(Coupon("A"), datetime(2026, 11, 10, 12, 0, tzinfo=SH))
        self.assertTrue(r["ok"])

    def test_redeem_rejects_after_expiry(self):
        r = redeem(Coupon("A"), datetime(2026, 11, 11, 12, 0, tzinfo=SH))
        self.assertFalse(r["ok"])
        self.assertEqual(r["reason"], "expired")

    def test_utc_absolute_equivalence(self):
        c = Coupon("A")
        self.assertFalse(c.is_expired(datetime(2026, 11, 10, 15, 59, 59, tzinfo=timezone.utc)))
        self.assertTrue(c.is_expired(datetime(2026, 11, 10, 16, 0, 0, tzinfo=timezone.utc)))


if __name__ == "__main__":
    unittest.main()
